package com.mediconnect.controller;
import com.mediconnect.dto.ApiDtos;import com.mediconnect.entity.Availability;import com.mediconnect.entity.User;import com.mediconnect.repository.AvailabilityRepository;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.time.DateTimeException;import java.time.LocalDate;import java.time.LocalTime;import java.util.List;import java.util.Map;
@RestController @RequestMapping("/api/availability") @PreAuthorize("hasRole('DOCTOR')")
public class AvailabilityController {private final AvailabilityRepository repo;public AvailabilityController(AvailabilityRepository repo){this.repo=repo;}@GetMapping public List<ApiDtos.AvailabilityView> mine(@AuthenticationPrincipal User u){return repo.findByDoctorIdOrderByDateAscStartTimeAsc(u.getId()).stream().map(ApiDtos.AvailabilityView::of).toList();}@PostMapping public ApiDtos.AvailabilityView add(@AuthenticationPrincipal User u,@RequestBody Map<String,Object>b){try{LocalDate date=LocalDate.parse(String.valueOf(b.get("date")));LocalTime start=LocalTime.parse(String.valueOf(b.get("startTime")));LocalTime end=LocalTime.parse(String.valueOf(b.get("endTime")));if(u.getHospital()==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Hospital membership required");if(date.isBefore(LocalDate.now())||!end.isAfter(start))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid date or time range");if(repo.existsOverlappingSession(u.getId(),date,start,end))throw new ResponseStatusException(HttpStatus.CONFLICT,"Availability sessions cannot overlap");Availability a=new Availability();a.setDoctor(u);a.setHospital(u.getHospital());a.setDate(date);a.setStartTime(start);a.setEndTime(end);a.setAvailable(true);return ApiDtos.AvailabilityView.of(repo.save(a));}catch(DateTimeException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid date or time",e);}}@DeleteMapping("/{id}") public void remove(@AuthenticationPrincipal User u,@PathVariable Long id){Availability a=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Slot not found"));if(!a.getDoctor().getId().equals(u.getId())||a.getHospital()==null||u.getHospital()==null||!a.getHospital().getId().equals(u.getHospital().getId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Not your slot");repo.delete(a);}}
